test('An early deliberate catch survives the release cooldown; there is no unsolicited magnetic catch',()=>{
 function launch(){const s=createState();Object.assign(s.p,{x:9,y:0,z:-5});interact(s);run(s,1.2,{forward:true});const r=RAILS.find(r=>r.id==='gale-loop'),p=[...r.pts].sort((a,b)=>Math.hypot(a.x-s.p.x,a.y-s.p.y-1.6,a.z-s.p.z)-Math.hypot(b.x-s.p.x,b.y-s.p.y-1.6,b.z-s.p.z))[0];s.p.yaw=Math.atan2(p.x-s.p.x,-(p.z-s.p.z));s.p.pitch=Math.atan2(p.y-s.p.y-1.6,Math.hypot(p.x-s.p.x,p.z-s.p.z));jump(s);return s;}
 const s=launch(),before=[s.p.x,s.p.y,s.p.z];assert.ok(s.p.hookCooldown>0);assert.ok(interact(s));assert.deepEqual([s.p.x,s.p.y,s.p.z],before);assert.equal(s.p.rail,null);run(s,.22,{forward:true});assert.equal(s.p.rail?.id,'gale-loop');assert.equal(s.stats.transfers,1);
 const untouched=launch();run(untouched,.3,{forward:true});assert.equal(untouched.p.rail,null);assert.equal(untouched.stats.transfers,0);
});
test('An expired catch request cannot attach later or survive rescue',()=>{const s=createState();Object.assign(s.p,{x:110,y:30,z:110,grounded:false,lastRail:'glassline',airSince:s.time,hookCooldown:.14});interact(s);assert.equal(s.p.hookRequest,.3);run(s,.4);assert.equal(s.p.hookRequest,0);assert.equal(s.p.rail,null);rescue(s);assert.equal(s.p.hookRequest,0);assert.equal(s.p.lastRail,null);});
test('Incoming rail momentum above cruise speed decays instead of being clipped at the next frame',()=>{const s=createState();Object.assign(s.p,{x:9,y:0,z:-5});interact(s);s.p.speed=25;step(s,{},dt);assert.ok(s.p.speed>24.9&&s.p.speed<25);run(s,.5);assert.ok(s.p.speed>23);});
